    case (state)
      S0: begin
        out1 = 1;
        out2 = 0;
      end
      S1: begin
        out1 = 0;
        out2 = 1;
      end
      S2: begin
        out1 = 1;
        out2 = 1;
      end
      S3: begin
        out1 = 0;
        out2 = 0;
      end
    endcase
  end

endmodule
