  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:0] c;
  wire [3:0] x;
  wire [3:0] y;

  // Full adder for the least significant bit
  full_adder FA0 (.a(A[0]), .b(B[0]), .ci(Ci), .s(S[0]), .co(c[0]));

  // Full adders for the remaining bits
  genvar i;
  generate
    for (i = 1; i < 4; i = i + 1) begin
      full_adder FA (.a(A[i]), .b(B[i]), .ci(c[i-1]), .s(S[i]), .co(c[i]));
    end
  endgenerate

