        .in(ena_out),
        .out(ena)
    );

    reg [15:0] count;
    reg [3:1] ena_reg;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            ena_reg <= 0;
        end
        else begin
            count <= count + 1;
            ena_reg <= ena_out;
        end
    end

    assign binary_out = count;
    assign ena_out = {3{1'b1}};

